def selection_sort(rec):
    n = len(rec)
    for i in range(n - 1):
        m = i
        for j in range(i + 1, n):
            if rec[j][0] < rec[m][0]:
                m = j
        rec[i], rec[m] = rec[m], rec[i]

queue = [(2, 'A'), (2, 'B'), (1, 'C'), (3, 'D'), (1, 'E'), (2, 'F'), (3, 'G'), (1, 'H')]
orig = list(queue)
selection_sort(queue)
pos = {t: i for i, (_, t) in enumerate(queue)}
rev = sum(1 for i in range(8) for j in range(i + 1, 8)
          if orig[i][0] == orig[j][0] and pos[orig[i][1]] > pos[orig[j][1]])
print(queue, rev)
